\resizebox{\columnwidth}{!}{%
\begin{tabular}{lrccc}
\toprule
\textbf{Mode} & \textbf{\# Batches} & \textbf{Precision} & \textbf{Recall} & \textbf{F1} \\
\midrule
single\_pass & 1 & 0.563 & 0.368 & 0.445 \\
\midrule
sdgd\_zero (v1) & 8 & 0.210 & 0.314 & 0.251 \\
